import { useDispatch, useSelector } from 'react-redux';

import { RootState } from 'app/appStore';
import { type OfferRead, setIsOpenDetailsPopup, setOffer, setVisitedOffer } from 'entities/Brand';

export const useBrandSlice = () => {
	const dispatch = useDispatch();

	return {
		...useSelector((s: RootState) => s.brandSlice),
		setOffer: (offset: OfferRead | null) => dispatch(setOffer(offset)),
		setIsOpenDetailsPopup: (offset: boolean) => dispatch(setIsOpenDetailsPopup(offset)),
		setVisitedOffer: (offset: string) => dispatch(setVisitedOffer(offset)),
	};
};
